/**
 * 负责本族加成效果运行记录的唯一数组，按原 NightStageState 对象身份保存。
 * 输入是夜间状态、原种类／领取回执／可选印记；输出是同一记录与数组引用，不复制、冻结或序列化运行句柄。
 * 读方获得只读数组视图，记录字段和嵌套回执仍保持原可变性；追加口仅取得数组，不提交回执或授予库存／行动权限。
 * 首次追加才建立数组；换状态对象不会继续旧夜记录，不读取或采纳旧 modifierBonusEffects 属性及其 getter。
 * 付款、原生命与当前性重验仍归本族阶段／frame；记录存在不代表已付、有效或已经造成死亡。
 */
import type { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import type { NightStageState } from "../../stages/night/contracts";
import type { ModifierBonusKind, ModifierBonusReceipt } from "./night_frame";

/** 三个原字段保持原类型与可变性；receipt／marks 是运行引用，不能移入玩家 DTO。 */
export interface ScholarMentorBonusEffectRecord {
  kind: ModifierBonusKind;
  receipt: ModifierBonusReceipt;
  marks?: StatusMarksComponent;
}

// 同一实际状态只有这一份数组；不在通用 NightStageState 字段上挂镜像或第二份索引。
const recordsByState = new WeakMap<NightStageState, ScholarMentorBonusEffectRecord[]>();

/** 未追加时返回原语义的临时空视图；查询不为状态预建记录，也不调用回执。 */
export function readScholarMentorBonusEffectRecords(
  state: NightStageState,
): readonly ScholarMentorBonusEffectRecord[] {
  return recordsByState.get(state) ?? [];
}

/** 原追加点先取得数组和 push callee，再创建效果条目；不提前捕获状态、回执或 marks。 */
export function scholarMentorBonusEffectRecordsForAppend(
  state: NightStageState,
): ScholarMentorBonusEffectRecord[] {
  let records = recordsByState.get(state);
  if (!records) {
    records = [];
    recordsByState.set(state, records);
  }
  return records;
}

/**
 * 单元测试验证本族加成记录的唯一数组、状态身份隔离及原效果重验顺序。
 * 输入为真实内存组件、手写回执／访问轨迹及明确旧属性注入；引用、字面拒绝和读序为独立预期。
 * 回执 commit 设置为失败哨兵，不运行整局或模型；数组／运行记录不授予付款、请求或生命写权。
 */
import { expect, test } from "bun:test";
import { World } from "../../../../src/core/domain/world";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import { createAliveComponent, aliveLifeVersion } from "../../../../src/core/domain/components/alive";
import { StatusMarksComponent } from "../../../../src/core/domain/components/status_marks";
import type { NightStageState, NightStageContext } from "../../../../src/game/mechanisms/stages/night/contracts";
import type { ModifierBonusKind, ModifierBonusReceipt } from "../../../../src/game/mechanisms/roles/scholar_mentor/night_frame";
import { assertScholarMentorBonusEffects } from "../../../../src/game/mechanisms/roles/scholar_mentor/night_stages";
import {
  readScholarMentorBonusEffectRecords,
  scholarMentorBonusEffectRecordsForAppend,
  type ScholarMentorBonusEffectRecord,
} from "../../../../src/game/mechanisms/roles/scholar_mentor/bonus-effect-records";

function state(): NightStageState {
  return { wolfChatOrder: [], endedWolves: new Set(), wolfVotes: {}, wolfTarget: null, seerChecks: [], dreamLinks: [] };
}
function fixture() {
  const world = new World(), id = world.createEntity(), life = createAliveComponent(), marks = new StatusMarksComponent();
  world.addComponent(id, COMPONENT.Alive, life);
  world.addComponent(id, COMPONENT.StatusMarks, marks);
  const target = { id, life, version: aliveLifeVersion(life)! };
  const receipt: ModifierBonusReceipt = {
    source: target, target, isCurrent: () => false, effectCurrent: () => true,
    commit() { throw new Error("commit_must_not_run"); },
  };
  return { world, marks, receipt, target };
}

test("one lazy array retains original records and mutable fields without attaching a generic slot", () => {
  const s = state(), other = state(), f = fixture();
  const record: ScholarMentorBonusEffectRecord = { kind: "guard", receipt: f.receipt, marks: f.marks };
  const firstEmpty = readScholarMentorBonusEffectRecords(s);
  expect(firstEmpty).toEqual([]);
  expect(readScholarMentorBonusEffectRecords(s)).not.toBe(firstEmpty);
  const rows = scholarMentorBonusEffectRecordsForAppend(s);
  rows.push(record);
  expect(readScholarMentorBonusEffectRecords(s)).toBe(rows);
  expect(scholarMentorBonusEffectRecordsForAppend(s)).toBe(rows);
  expect(rows[0]).toBe(record);
  expect(rows[0]!.receipt).toBe(f.receipt);
  expect(rows[0]!.marks).toBe(f.marks);
  expect(readScholarMentorBonusEffectRecords(other)).toEqual([]);
  expect(readScholarMentorBonusEffectRecords({ ...s })).toEqual([]);
  expect(Object.hasOwn(s, "modifierBonusEffects")).toBe(false);
  expect(Object.isFrozen(rows)).toBe(false);
  expect(Object.isFrozen(record)).toBe(false);
  // 原三字段和嵌套可变性双向相容，数组只读视图不等于深冻结。
  type OldRecord = { kind: ModifierBonusKind; receipt: ModifierBonusReceipt; marks?: ReturnType<NightStageContext["ensureMarks"]> };
  const oldShape: OldRecord = record, sameShape: ScholarMentorBonusEffectRecord = oldShape;
  sameShape.kind = "check";
  expect(rows[0]!.kind).toBe("check");
  // 此实际编译负例必须由新的key契约拒绝，删除字段后不能留下旧出口。
  // @ts-expect-error modifierBonusEffects 已退出通用 NightStageState。
  const retiredKey: keyof NightStageState = "modifierBonusEffects";
  expect(retiredKey as string).toBe("modifierBonusEffects");
});

test("effect recheck keeps target then callback then life and marks reads and never commits a receipt", () => {
  const f = fixture(), s = state(), trace: string[] = [];
  let current = true;
  const receipt: ModifierBonusReceipt = {
    ...f.receipt,
    get target() { trace.push("target"); return f.target; },
    effectCurrent() { trace.push("current"); return current; },
  };
  const record: ScholarMentorBonusEffectRecord = {
    kind: "guard", receipt,
    get marks() { trace.push("marks"); return f.marks; },
  };
  const rows = scholarMentorBonusEffectRecordsForAppend(s);
  rows.push(record);
  let activeState = s;
  const ctx = {
    get world() { trace.push("world"); return f.world; },
    get state() { trace.push("state"); return activeState; },
  } as unknown as NightStageContext;
  assertScholarMentorBonusEffects(ctx);
  expect(trace).toEqual(["world", "state", "target", "current", "world", "marks", "world", "marks"]);
  current = false; trace.length = 0;
  expect(() => assertScholarMentorBonusEffects(ctx)).toThrow("scholar_mentor_bonus_effect_stale");
  expect(trace).toEqual(["world", "state", "target", "current"]);
  current = true; trace.length = 0;
  f.world.addComponent(f.target.id, COMPONENT.StatusMarks, new StatusMarksComponent());
  expect(() => assertScholarMentorBonusEffects(ctx)).toThrow("scholar_mentor_bonus_effect_stale");
  expect(rows).toEqual([record]);
  // 换同形状态不继承原记录；原数组和已经发生的写入不被清理或退款。
  activeState = { ...s }; trace.length = 0;
  expect(() => assertScholarMentorBonusEffects(ctx)).not.toThrow();
  expect(trace).toEqual(["world", "state"]);
  expect(readScholarMentorBonusEffectRecords(s)).toBe(rows);
});

test("retired generic property injection is not consulted or treated as an owned receipt", () => {
  const s = state(), world = new World(), trace: string[] = [];
  Object.defineProperty(s, "modifierBonusEffects", {
    get() { trace.push("retiredSlot"); throw new Error("retired_getter_must_not_run"); },
  });
  const ctx = { world, get state() { trace.push("state"); return s; } } as unknown as NightStageContext;
  expect(() => assertScholarMentorBonusEffects(ctx)).not.toThrow();
  expect(trace).toEqual(["state"]);
  expect(readScholarMentorBonusEffectRecords(s)).toEqual([]);
});
